{
  "case_id": "xsu_sg_009_medical_documentation_content",
  "criteria": {
    "c01_overall_legal_correctness": {
      "label": "met",
      "reason": "De seks punkter gengiver afsnit 4.2 korrekt, inklusive forbeholdene 'hvis der er stillet en', 'hvis der er planlagt en' og 'hvis muligt'. Svaret gør hverken diagnose eller planlagt behandling ubetinget, og det udlægger ikke afsnittet som en pligt til at købe ny dokumentation. Slutsætningen om tilgængelighed i journalen eller anden eksisterende lægefaglig dokumentation stemmer med kilden. Der er ingen væsentlig juridisk fejl."
    },
    "c02_required_elements_complete": {
      "label": "not_met",
      "reason": "Svaret mangler flere kritiske elementer i rubrikken. Det nævner ikke, at dokumentationen skal være relevant og aktuel. Det beskriver ikke, at den skal vise den varige funktionsnedsættelses art og grad. Udredningsforløbet er heller ikke nævnt, kun sygdoms- og behandlingsforløb. Punkterne om diagnose, behandling og erhvervsevne samt tilgængelighed i journalen er med."
    },
    "c03_direct_relevance": {
      "label": "met",
      "reason": "Svaret er en punktopstilling, der direkte besvarer, hvad den lægelige dokumentation skal beskrive. Der er ingen irrelevant tekst."
    },
    "c04_source_traceability": {
      "label": "not_met",
      "reason": "Svaret angiver ingen identificerbar kilde som bekendtgørelse, lov eller vejledningsafsnit. Det henviser ikke til afsnit 4.2 eller til SU-bekendtgørelsen § 37."
    },
    "c05_source_validity": {
      "label": "not_assessable",
      "reason": "Der er ikke angivet nogen kilde, så gyldigheden kan ikke vurderes."
    },
    "c06_claim_source_support": {
      "label": "not_assessable",
      "reason": "Der er ikke angivet nogen kilde, så det kan ikke bedømmes, om kilder støtter påstandene."
    },
    "c07_no_unsupported_legal_additions": {
      "label": "met",
      "reason": "Svaret tilføjer ingen regler, betingelser eller retsvirkninger ud over afsnit 4.2. Alle seks punkter og tilgængelighedsforbeholdet findes i kilden."
    },
    "c08_qualifications_and_exceptions": {
      "label": "met",
      "reason": "Forbeholdene 'hvis der er stillet en', 'hvis der er planlagt en' og 'hvis muligt' er bevaret. Tilgængelighedsforbeholdet om journalen eller anden eksisterende lægefaglig dokumentation er også med. Svaret tilføjer ikke, at dokumentationsminimum bortfalder."
    },
    "c09_reasoning_coherence": {
      "label": "met",
      "reason": "Svaret er en enkel og konsistent opstilling. Konklusionen følger af punkterne, og der er ingen modsigelser."
    },
    "c10_legal_modality_precision": {
      "label": "met",
      "reason": "'Skal beskrive' svarer til kildens 'ved aktuel og fyldestgørende dokumentation menes' og 'skal fremsendes'. De betingede punkter er bevaret som betingede. Intet gøres valgfrit eller absolut."
    }
  },
  "xhaile_coverage": {
    "A39": {
      "label": "yes",
      "reason": "Punkt 1 nævner diagnosen 'hvis der er stillet en'."
    },
    "A41": {
      "label": "yes",
      "reason": "Punkt 2 nævner beskrivelse af sygdoms- og behandlingsforløbet."
    },
    "A42": {
      "label": "yes",
      "reason": "Punkt 2 dækker behandlingsforløbet, og punkt 4 dækker den aktuelle behandling."
    },
    "A45": {
      "label": "yes",
      "reason": "Punkt 5 nævner planlagt behandling 'hvis der er planlagt en'."
    },
    "A47": {
      "label": "yes",
      "reason": "Punkt 6 nævner påvirkning af erhvervsevnen 'hvis muligt'."
    }
  },
  "overall_notes": "Svaret er en trofast gengivelse af listen i vejledningens afsnit 4.2, med forbehold og modalitet bevaret. Det udelader dog den indledende ramme om relevant og aktuel dokumentation af den varige funktionsnedsættelses art og grad samt udredningsforløbet, så C02 er not_met. Svaret citerer ingen kilde, så C04 er not_met, og C05 og C06 er not_assessable."
}

